// Reads the active brand's primitives (plugins/branding/registry.ts) and
// writes src/styles/tokens.css. Never hand-edit the generated file.
import { writeFile, readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");

async function loadPrimitives() {
  const brandId = process.env.ACTIVE_BRAND ?? "zsyio-default";
  const candidatePaths = [
    path.join(root, "plugins", "branding", brandId, "primitives.json"),
    path.join(root, "tokens", "primitives.json"),
  ];
  for (const p of candidatePaths) {
    try {
      const raw = await readFile(p, "utf-8");
      return JSON.parse(raw);
    } catch {
      continue;
    }
  }
  throw new Error(`No primitives.json found for brand "${brandId}"`);
}

function css(primitives) {
  const { color, radius, space, font, shadow } = primitives;

  const primitiveVars = [];
  for (const [family, shades] of Object.entries(color)) {
    for (const [shade, value] of Object.entries(shades)) {
      primitiveVars.push(`  --color-${family}-${shade}: ${value};`);
    }
  }
  for (const [key, value] of Object.entries(radius)) {
    primitiveVars.push(`  --radius-${key}: ${value};`);
  }
  for (const [key, value] of Object.entries(space)) {
    primitiveVars.push(`  --space-${key}: ${value};`);
  }
  for (const [key, value] of Object.entries(font.size)) {
    primitiveVars.push(`  --font-size-${key}: ${value};`);
  }
  primitiveVars.push(`  --font-display: ${font.family.display};`);
  primitiveVars.push(`  --font-body: ${font.family.body};`);
  primitiveVars.push(`  --font-mono: ${font.family.mono};`);
  for (const [key, value] of Object.entries(shadow)) {
    primitiveVars.push(`  --shadow-${key}: ${value};`);
  }

  return `/* AUTO-GENERATED by scripts/build-tokens.mjs — do not hand-edit */
:root {
${primitiveVars.join("\n")}

  /* ── Semantic tokens - Notion Utilitarian & Warm Minimalist System (light-first) ── */
  --background:              #FBFBFA;
  --foreground:              #37352F;
  --foreground-secondary:    #787774;
  --foreground-tertiary:     #9B9A97;
  --foreground-disabled:     #C5C4C0;

  --surface-elevated:        #FFFFFF;
  --surface-card:            #FFFFFF;
  --surface-overlay:         rgba(251, 251, 250, 0.96);
  --surface-subtle:          #F7F6F3;

  --border:                  rgba(55, 53, 47, 0.09);
  --border-strong:           rgba(55, 53, 47, 0.16);
  --border-focus:            #2383E2;

  --primary:                 #2383E2;
  --primary-hover:           #1D70C2;
  --primary-light:           #E7F3F8;
  --primary-foreground:      #FFFFFF;

  --destructive:             #EB5757;
  --destructive-hover:       #D94848;
  --destructive-light:       #FDEBEC;
  --destructive-foreground:  #FFFFFF;

  --success:                 #448361;
  --success-light:           #EDF3EC;
  --warning:                 #C29243;
  --warning-light:           #FBF3DB;

  --muted:                   #F1F1EF;
  --muted-foreground:        #787774;

  --accent:                  #E7F3F8;
  --accent-foreground:       #2383E2;

  --secondary:               #F7F6F3;
  --secondary-foreground:    #37352F;

  --card:                    #FFFFFF;
  --card-foreground:         #37352F;

  --popover:                 #FFFFFF;
  --popover-foreground:      #37352F;

  --input:                   #FFFFFF;
  --input-border:            rgba(55, 53, 47, 0.16);
  --ring:                    #2383E2;

  --radius:                  var(--radius-md);

  /* ── Status & Priority Chart Tokens (Restrained & Harmonious) ── */
  --color-status-todo:       #787774;
  --color-status-in-progress: #2383E2;
  --color-status-in-review:  #9065B0;
  --color-status-qa:         #C29243;
  --color-status-blocked:    #EB5757;
  --color-status-done:       #448361;
  --color-status-backlog:    #9B9A97;

  --color-priority-critical: #EB5757;
  --color-priority-high:     #CC782F;
  --color-priority-medium:   #2383E2;
  --color-priority-low:      #9B9A97;

  --chart-grid:              rgba(55, 53, 47, 0.08);
  --chart-axis:              #787774;
}

.dark,
[data-theme="dark"] {
  /* Dark theme overrides - Deep Obsidian & High-Contrast Slate System */
  --background:              #0D0F12;
  --foreground:              #F1F3F7;
  --foreground-secondary:    #9DA4B2;
  --foreground-tertiary:     #687082;
  --foreground-disabled:     #454B58;

  --surface-elevated:        #1E222B;
  --surface-card:            #15181E;
  --surface-overlay:         rgba(13, 15, 18, 0.96);
  --surface-subtle:          #111317;

  --border:                  rgba(255, 255, 255, 0.08);
  --border-strong:           rgba(255, 255, 255, 0.15);
  --border-focus:            #3B82F6;

  --primary:                 #3B82F6;
  --primary-hover:           #60A5FA;
  --primary-light:           rgba(59, 130, 246, 0.15);
  --primary-foreground:      #FFFFFF;

  --destructive:             #F87171;
  --destructive-hover:       #EF4444;
  --destructive-light:       rgba(248, 113, 113, 0.15);
  --destructive-foreground:  #FFFFFF;

  --success:                 #34D399;
  --success-light:           rgba(52, 211, 153, 0.15);
  --warning:                 #FBBF24;
  --warning-light:           rgba(251, 191, 36, 0.15);

  --muted:                   #181B22;
  --muted-foreground:        #9DA4B2;

  --accent:                  rgba(59, 130, 246, 0.15);
  --accent-foreground:       #60A5FA;

  --secondary:               #15181E;
  --secondary-foreground:    #F1F3F7;

  --card:                    #15181E;
  --card-foreground:         #F1F3F7;

  --popover:                 #1E222B;
  --popover-foreground:      #F1F3F7;

  --input:                   #111317;
  --input-border:            rgba(255, 255, 255, 0.12);
  --ring:                    #3B82F6;

  --shadow-sm:               0 1px 2px rgba(0, 0, 0, 0.5);
  --shadow-md:               0 4px 16px -2px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(255, 255, 255, 0.06);

  --color-status-todo:       #9DA4B2;
  --color-status-in-progress: #3B82F6;
  --color-status-in-review:  #A78BFA;
  --color-status-qa:         #FBBF24;
  --color-status-blocked:    #F87171;
  --color-status-done:       #34D399;
  --color-status-backlog:    #687082;

  --color-priority-critical: #F87171;
  --color-priority-high:     #FB923C;
  --color-priority-medium:   #3B82F6;
  --color-priority-low:      #687082;

  --chart-grid:              rgba(255, 255, 255, 0.06);
  --chart-axis:              #9DA4B2;
}
`;
}

import { mkdir } from "node:fs/promises";

const primitives = await loadPrimitives();
const cssContent = css(primitives);

const outPaths = [
  path.join(root, "packages", "ui", "src", "styles", "tokens.css"),
  path.join(root, "apps", "pms", "src", "styles", "tokens.css"),
  path.join(root, "apps", "notes", "src", "styles", "tokens.css"),
  path.join(root, "apps", "admin", "src", "styles", "tokens.css"),
  path.join(root, "apps", "hrms", "src", "styles", "tokens.css"),
  path.join(root, "apps", "sales", "src", "styles", "tokens.css"),
];

for (const outPath of outPaths) {
  try {
    const parentDir = path.dirname(outPath);
    await mkdir(parentDir, { recursive: true });
    await writeFile(outPath, cssContent, "utf-8");
    console.log(`tokens.css generated -> ${path.relative(root, outPath)}`);
  } catch (err) {
    console.error(`Failed to write tokens.css to ${path.relative(root, outPath)}:`, err);
  }
}

